CHILD = 'import ast, hashlib, json, os, pathlib, shutil, stat, subprocess, tempfile\nCORE = \'#!/usr/bin/env python3\\n"""Semaphore\\\'s external update outcome, idle check and matched rollback."""\\nimport datetime\\nfrom contextlib import closing\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport re\\nimport shutil\\nimport sqlite3\\nimport subprocess\\nimport sys\\nimport time\\nimport urllib.request\\n\\nDATABASE = Path(\\\'/var/lib/semaphore/database.sqlite\\\')\\nSTATE = Path(\\\'/var/www/maintenance-status/controller-update.json\\\')\\nBINARY = Path(\\\'/usr/local/bin/semaphore\\\')\\nCONFIG = \\\'/etc/semaphore/config.json\\\'\\n\\ndef write_state(status, version=\\\'\\\', operation=\\\'\\\', phase=\\\'\\\'):\\n    temporary = STATE.with_suffix(\\\'.json.tmp\\\')\\n    temporary.write_text(json.dumps({\\n        \\\'status\\\': status, \\\'version\\\': version, \\\'operation\\\': operation,\\n        \\\'phase\\\': phase, \\\'updated_at\\\': datetime.datetime.now(datetime.timezone.utc).isoformat(),\\n    }) + \\\'\\\\n\\\')\\n    temporary.chmod(0o644)\\n    os.replace(temporary, STATE)\\n\\ndef wait_idle(database=DATABASE, timeout=600):\\n    deadline = time.monotonic() + timeout\\n    while True:\\n        with closing(sqlite3.connect(database.as_uri() + \\\'?mode=ro\\\', uri=True)) as connection:\\n            active = connection.execute(\\n                "SELECT count(*) FROM task WHERE runner_id IS NULL "\\n                "AND status NOT IN (\\\'success\\\',\\\'error\\\',\\\'stopped\\\')"\\n            ).fetchone()[0]\\n        if not active:\\n            return\\n        if time.monotonic() >= deadline:\\n            raise RuntimeError(\\\'local tasks still active; service was not stopped\\\')\\n        time.sleep(1)\\n\\ndef recover():\\n    # Retained for the existing Home ExecStartPre; no Edge hook is added.\\n    with closing(sqlite3.connect(DATABASE, timeout=5)) as connection, connection:\\n        rows = connection.execute(\\n            "SELECT id FROM task WHERE runner_id IS NULL "\\n            "AND status IN (\\\'running\\\',\\\'starting\\\',\\\'stopping\\\')"\\n        ).fetchall()\\n        for (task_id,) in rows:\\n            now = datetime.datetime.now(datetime.timezone.utc).isoformat()\\n            connection.execute("UPDATE task SET status=\\\'error\\\', end=? WHERE id=?", (now, task_id))\\n            connection.execute(\\\'INSERT INTO task__output(task_id,time,output) VALUES (?,?,?)\\\',\\n                               (task_id, now, \\\'Interrupted by Semaphore service restart; local worker no longer exists.\\\'))\\n            print(f\\\'CONTROLLER_RECOVERED_INTERRUPTED_TASK={task_id}\\\', flush=True)\\n\\ndef run(argv):\\n    subprocess.run(argv, check=True)\\n\\ndef binary_version(path):\\n    text = subprocess.check_output([str(path), \\\'version\\\'], text=True).strip()\\n    match = re.match(r\\\'[0-9]+\\\\.[0-9]+\\\\.[0-9]+\\\', text)\\n    if not match:\\n        raise RuntimeError(\\\'unrecognized Semaphore binary version\\\')\\n    return match.group()\\n\\ndef copy_database(source, destination):\\n    with closing(sqlite3.connect(source.as_uri() + \\\'?mode=ro\\\', uri=True)) as src:\\n        with closing(sqlite3.connect(destination)) as dst:\\n            src.backup(dst)\\n\\ndef healthy(version):\\n    for attempt in range(30):\\n        try:\\n            pid = int(subprocess.check_output(\\n                [\\\'systemctl\\\', \\\'show\\\', \\\'semaphore\\\', \\\'-p\\\', \\\'MainPID\\\', \\\'--value\\\'], text=True).strip())\\n            if pid > 0:\\n                with urllib.request.urlopen(\\\'http://127.0.0.1:3000/api/ping\\\', timeout=5) as response:\\n                    if response.status == 200 and binary_version(Path(\\\'/proc\\\') / str(pid) / \\\'exe\\\') == version:\\n                        return\\n        except (OSError, ValueError, subprocess.SubprocessError):\\n            pass\\n        time.sleep(1)\\n    raise RuntimeError(\\\'Semaphore ping/running-version check failed\\\')\\n\\ndef install_semaphore(candidate, version, database, backup, backup_db):\\n    if binary_version(candidate) != version:\\n        raise RuntimeError(\\\'downloaded binary version mismatch\\\')\\n    wait_idle(database)\\n    previous_version = binary_version(BINARY)\\n    shutil.copy2(BINARY, backup)\\n    backup.chmod(0o600)\\n    stopped = False\\n    database_saved = False\\n    try:\\n        run([\\\'systemctl\\\', \\\'stop\\\', \\\'semaphore\\\'])\\n        stopped = True\\n        # Cold, matched SQLite backup before any schema/binary changes.\\n        backup_db.touch(mode=0o600, exist_ok=True)\\n        backup_db.chmod(0o600)\\n        copy_database(database, backup_db)\\n        database_saved = True\\n        shutil.copy2(candidate, BINARY)\\n        BINARY.chmod(0o755)\\n        run([\\\'runuser\\\', \\\'-u\\\', \\\'semaphore\\\', \\\'--\\\', str(BINARY), \\\'migrate\\\', \\\'--config\\\', CONFIG])\\n        run([\\\'systemctl\\\', \\\'start\\\', \\\'semaphore\\\'])\\n        healthy(version)\\n    except Exception as failure:\\n        if stopped:\\n            try:\\n                run([\\\'systemctl\\\', \\\'stop\\\', \\\'semaphore\\\'])\\n                shutil.copy2(backup, BINARY)\\n                BINARY.chmod(0o755)\\n                if database_saved:\\n                    copy_database(backup_db, database)\\n                run([\\\'systemctl\\\', \\\'start\\\', \\\'semaphore\\\'])\\n                healthy(previous_version)\\n                print(\\\'SEMAPHORE_ROLLBACK=VERIFIED\\\', flush=True)\\n            except Exception as rollback_failure:\\n                raise RuntimeError(\\\'rollback failed; retain backup pair and inspect service\\\') from rollback_failure\\n        raise failure\\n\\nif __name__ == \\\'__main__\\\':\\n    command = sys.argv[1]\\n    if command == \\\'wait-idle\\\':\\n        wait_idle()\\n    elif command == \\\'recover\\\':\\n        recover()\\n    elif command in (\\\'pending\\\', \\\'success\\\', \\\'error\\\'):\\n        arguments = sys.argv[2:5]\\n        preserve_error = False\\n        if command == \\\'error\\\' and len(arguments) >= 2 and STATE.exists():\\n            existing = json.loads(STATE.read_text())\\n            preserve_error = existing.get(\\\'status\\\') == \\\'error\\\' and existing.get(\\\'operation\\\') == arguments[1]\\n        if not preserve_error:\\n            write_state(command, *arguments)\\n    elif command == \\\'install\\\':\\n        candidate, version, operation, backup, backup_db, refresh = sys.argv[2:8]\\n        try:\\n            install_semaphore(Path(candidate), version, DATABASE, Path(backup), Path(backup_db))\\n        except Exception:\\n            write_state(\\\'error\\\', version, operation, \\\'install-or-rollback\\\')\\n            raise\\n        try:\\n            run([refresh])\\n        except Exception:\\n            # A status refresh failure does not undo a healthy updated service.\\n            write_state(\\\'error\\\', version, operation, \\\'status-refresh\\\')\\n            raise\\n        write_state(\\\'success\\\', version, operation, \\\'verified\\\')\\n        print(\\\'SEMAPHORE_UPDATE=SUCCESS|VERSION=\\\' + version, flush=True)\\n    else:\\n        raise SystemExit(\\\'Unknown controller update command\\\')\\n\'\nBRANCH = \'    SEMAPHORE_CONTROLLER)\\n        exec {SEM_LOCK_FD}>/run/lock/semaphore-controller-update.lock\\n        flock -n "$SEM_LOCK_FD" || { echo \\\'SEMAPHORE_UPDATE=ALREADY_DISPATCHING\\\' >&2; exit 73; }\\n        if systemctl show semaphore-controller-update.service -p ActiveState --value 2>/dev/null | grep -Eq \\\'^(active|activating|deactivating)$\\\'; then\\n            echo \\\'SEMAPHORE_UPDATE=ALREADY_RUNNING\\\' >&2\\n            exit 73\\n        fi\\n        OLD="$(pct exec 1000 -- /usr/local/bin/semaphore version | grep -oE \\\'^[0-9]+\\\\.[0-9]+\\\\.[0-9]+\\\')"\\n        LATEST_TAG="$(github_latest_tag semaphoreui/semaphore)"\\n        LATEST="${LATEST_TAG#v}"\\n        [[ "$LATEST" =~ ^[0-9]+\\\\.[0-9]+\\\\.[0-9]+$ ]]\\n        echo "SEMAPHORE_CURRENT_VERSION=$OLD"\\n        echo "SEMAPHORE_LATEST_VERSION=$LATEST"\\n        NEW="$OLD"\\n        if [ "$OLD" = "$LATEST" ]; then\\n            echo \\\'SEMAPHORE_CONTROLLER_STATUS=ALREADY_UP_TO_DATE\\\'\\n        else\\n            (\\n                set -Eeuo pipefail\\n                WORK="$(mktemp -d /tmp/semaphore-update.XXXXXXXX)"\\n                OPERATION="${WORK##*/}"\\n                STAGE="/tmp/semaphore-staging/$OPERATION"\\n                HANDED_OFF=0\\n                cleanup_preparation() {\\n                    rm -rf -- "$WORK"\\n                    if [ "$HANDED_OFF" -eq 0 ]; then\\n                        pct exec 1000 -- rm -rf -- "$STAGE" || true\\n                        pct exec 1000 -- rmdir /tmp/semaphore-staging 2>/dev/null || true\\n                    fi\\n                }\\n                trap cleanup_preparation EXIT\\n                ASSET="semaphore_${LATEST}_linux_amd64.tar.gz"\\n                BASE="https://github.com/semaphoreui/semaphore/releases/download/$LATEST_TAG"\\n                curl -fsSL --connect-timeout 10 --max-time 120 "$BASE/$ASSET" -o "$WORK/$ASSET"\\n                curl -fsSL --connect-timeout 10 --max-time 60 "$BASE/semaphore_${LATEST}_checksums.txt" -o "$WORK/checksums"\\n                EXPECTED="$(awk -v n="$ASSET" \\\'$2==n || $2=="*"n {print $1; exit}\\\' "$WORK/checksums")"\\n                [[ "$EXPECTED" =~ ^[0-9a-fA-F]{64}$ ]]\\n                ACTUAL="$(sha256sum "$WORK/$ASSET" | cut -d\\\' \\\' -f1)"\\n                test "$EXPECTED" = "$ACTUAL"\\n                tar -xzf "$WORK/$ASSET" -C "$WORK" semaphore\\n                chmod 755 "$WORK/semaphore"\\n                test "$("$WORK/semaphore" version | grep -oE \\\'^[0-9]+\\\\.[0-9]+\\\\.[0-9]+\\\')" = "$LATEST"\\n                pct exec 1000 -- mkdir -p "$STAGE"\\n                pct push 1000 "$WORK/semaphore" "$STAGE/semaphore"\\n                pct exec 1000 -- chmod 755 "$STAGE/semaphore"\\n                pct exec 1000 -- /opt/maintenance-repo/scripts/controller-update-state pending "$LATEST" "$OPERATION"\\n                if ! systemd-run --unit=semaphore-controller-update --collect --service-type=exec \\\\\\n                    --description=\\\'Semaphore Controller Binary Update\\\' \\\\\\n                    /bin/bash -c \\\'\\n                        set -Eeuo pipefail\\n                        candidate="$1"; version="$2"; operation="$3"; stage="$4"\\n                        cleanup_worker() {\\n                            rc=$?\\n                            if [ "$rc" -ne 0 ]; then\\n                                pct exec 1000 -- /opt/maintenance-repo/scripts/controller-update-state error "$version" "$operation" || true\\n                            fi\\n                            pct exec 1000 -- rm -rf -- "$stage" || true\\n                            pct exec 1000 -- rmdir /tmp/semaphore-staging 2>/dev/null || true\\n                        }\\n                        trap cleanup_worker EXIT\\n                        pct exec 1000 -- /opt/maintenance-repo/scripts/controller-update-state install \\\\\\n                            "$candidate" "$version" "$operation" \\\\\\n                            /usr/local/bin/semaphore.pre-update /var/lib/semaphore/database.sqlite.pre-update \\\\\\n                            /opt/maintenance-repo/scripts/maintenance-targets-refresh\\n                    \\\' -- "$STAGE/semaphore" "$LATEST" "$OPERATION" "$STAGE"; then\\n                    pct exec 1000 -- /opt/maintenance-repo/scripts/controller-update-state error "$LATEST" "$OPERATION"\\n                    exit 1\\n                fi\\n                HANDED_OFF=1\\n                echo "SEMAPHORE_UPDATE_ID=$OPERATION"\\n                echo \\\'SEMAPHORE_CONTROLLER_STATUS=UPGRADE_DISPATCHED_TO_TRANSIENT_UNIT\\\'\\n            )\\n            UPDATE_RESULT=DISPATCHED\\n        fi\\n        exec {SEM_LOCK_FD}>&-\\n        ;;\\n\'\nWAIT = \'    async function waitControllerUpdate(taskId) {\\n      const response = await fetch(`/api/project/1/tasks/${taskId}/output`, {cache: "no-store", signal: AbortSignal.timeout(10000)});\\n      if (!response.ok) throw new Error(`Cannot read update outcome: HTTP ${response.status}`);\\n      const output = (await response.json()).map(line => line.output || "").join("\\\\n");\\n      const operation = output.match(/SEMAPHORE_UPDATE_ID=([A-Za-z0-9_.-]+)/)?.[1];\\n      if (!operation) return;\\n      showToast("Waiting for Semaphore update and health check...", "info");\\n      for (let i = 0; i < 330; i++) {\\n        await new Promise(resolve => setTimeout(resolve, 2000));\\n        let state;\\n        try {\\n          const result = await fetch("/status/controller-update.json", {cache: "no-store", signal: AbortSignal.timeout(10000)});\\n          if (result.ok) state = await result.json();\\n        } catch (error) { continue; }\\n        if (state?.operation !== operation) continue;\\n        if (state.status === "error") throw new Error("Semaphore update failed; inspect its external unit journal.");\\n        if (state.status === "success") return;\\n      }\\n      throw new Error("Semaphore update outcome is still pending; inspect its external unit journal.");\\n    }\\n\\n\'\nEXPECTED = \'c0d3f0e0e68dad2c11ab02b48c6eb5f91c78982cbdf8f06f4486c78a9a50153c\'\n\ndef prepare(repo, web, expected=EXPECTED):\n    manual=repo/\'scripts/manual-update\'\n    old=manual.read_text()\n    if hashlib.sha256(manual.read_bytes()).hexdigest()!=expected:\n        raise RuntimeError(\'manual-update differs from audited source; no changes made\')\n    marker=\'    SEMAPHORE_CONTROLLER)\\n        echo "SEMAPHORE_CONTROLLER_UPDATE_PHASE=PRECHECK"\'\n    if old.count(marker)!=1: raise RuntimeError(\'ambiguous Semaphore branch\')\n    a=old.index(marker);b=old.index(\'\\n        ;;\',a)+len(\'\\n        ;;\\n\')\n    changes={manual:old[:a]+BRANCH+old[b:], repo/\'scripts/controller-update-state\':CORE}\n    playbook=repo/\'playbooks/manual-update.yml\'\n    play=playbook.read_text()\n    if play.count(\'    - name: Подтвердить отсутствие recovery действий\')!=1:\n        raise RuntimeError(\'playbook differs from audit\')\n    changes[playbook]=play+\'      when: maintenance_target != \\\'SEMAPHORE_CONTROLLER\\\'\\n\\n    - name: Show Semaphore update phase\\n      ansible.builtin.debug:\\n        msg: "Controller task finished; use controller-update.json and the external unit journal for the final outcome."\\n      when: maintenance_target == \\\'SEMAPHORE_CONTROLLER\\\'\\n\'\n    for page in dict.fromkeys([web/\'index.html\', repo/\'dashboard/index.html\']):\n        if not page.exists():\n            if page==web/\'index.html\':raise RuntimeError(\'live dashboard not found\')\n            continue\n        html=page.read_text()\n        start=html.index(\'    async function waitControllerUpdate(taskId) {\')\n        end=html.index(\'    async function pollTask(\',start)\n        changes[page]=html[:start]+WAIT+html[end:]\n    for path in changes:\n        if path.is_symlink(): raise RuntimeError(\'symlink requires targeted review: \'+str(path))\n    ast.parse(CORE)\n    with tempfile.TemporaryDirectory(prefix=\'semaphore-fix-validate-\') as temporary:\n        candidate=pathlib.Path(temporary)/\'manual-update\'\n        candidate.write_text(changes[manual])\n        subprocess.run([\'bash\',\'-n\',str(candidate)],check=True)\n    return changes\n\ndef install(changes, recovery, backup_files=(\'/usr/local/bin/semaphore.pre-update\',\'/var/lib/semaphore/database.sqlite.pre-update\')):\n    if recovery.exists():raise RuntimeError(\'recovery directory already exists; preserve it\')\n    recovery.mkdir(mode=0o700)\n    records=[]\n    for index,(path,data) in enumerate(changes.items()):\n        info=path.stat();saved=recovery/str(index)\n        shutil.copy2(path,saved);saved.chmod(0o600)\n        records.append({\'path\':str(path),\'saved\':str(saved),\'uid\':info.st_uid,\'gid\':info.st_gid,\'mode\':stat.S_IMODE(info.st_mode)})\n    for name in backup_files:\n        p=pathlib.Path(name)\n        if p.exists():records.append({\'path\':name,\'mode_only\':True,\'mode\':stat.S_IMODE(p.stat().st_mode)})\n    manifest=recovery/\'manifest.json\';manifest.write_text(json.dumps(records,indent=2)+\'\\n\');manifest.chmod(0o600)\n    try:\n        for path,data in changes.items():\n            path.write_text(data)\n        for record in records:\n            if record.get(\'mode_only\'):pathlib.Path(record[\'path\']).chmod(0o600)\n        for path,data in changes.items():\n            if path.read_text()!=data:raise RuntimeError(\'readback mismatch\')\n    except Exception:\n        for record in records:\n            p=pathlib.Path(record[\'path\'])\n            if not record.get(\'mode_only\'):shutil.copy2(record[\'saved\'],p);os.chown(p,record[\'uid\'],record[\'gid\'])\n            p.chmod(record[\'mode\'])\n        raise\n\nif __name__==\'__main__\':\n    repo=pathlib.Path(\'/opt/maintenance-repo\');web=pathlib.Path(\'/var/www/maintenance-status\')\n    before=subprocess.check_output([\'systemctl\',\'show\',\'semaphore\',\'-p\',\'MainPID\',\'-p\',\'ExecMainStartTimestamp\'])\n    configuration=json.loads(pathlib.Path(\'/etc/semaphore/config.json\').read_text())\n    if configuration.get(\'dialect\')!=\'sqlite\' or configuration[\'sqlite\'][\'host\']!=\'/var/lib/semaphore/database.sqlite\':\n        raise RuntimeError(\'unexpected database configuration; no changes made\')\n    changes=prepare(repo,web)\n    recovery=pathlib.Path(\'/tmp/semaphore-handler-recovery\')\n    install(changes,recovery)\n    after=subprocess.check_output([\'systemctl\',\'show\',\'semaphore\',\'-p\',\'MainPID\',\'-p\',\'ExecMainStartTimestamp\'])\n    if before!=after:raise RuntimeError(\'service changed concurrently; inspect before acceptance\')\n    print(\'PVE_SEMAPHORE_HANDLER_FIX=PASS|REAL_UPDATE_EXECUTED=NO|SERVICE_RESTARTS=NO\')\n    print(\'RECOVERY=\'+str(recovery))\n    for p in changes:print(\'CHANGED=\'+str(p))\n'
if __name__ == '__main__':
    if os.geteuid()!=0:raise SystemExit('Run on PVE as root')
